/* @lc app=leetcode id=1627 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = if (p[x] == x) x else find(p, p[x]).also { p[x] = it } fun areConnected(n: Int, threshold: Int, queries: Array<IntArray>): List<Boolean> = IntArray(n + 1) { it }.let { p -> (threshold + 1..n).forEach { z -> (2 * z..n step z).forEach { m -> p[find(p, m)] = find(p, z) } }.let { queries.map { find(p, it[0]) == find(p, it[1]) } } } }